e_master:edit,route_master:delete,region:view,region:create,region:edit,region:delete,province:view,province:create,province:edit,province:delete,district:view,district:create,district:edit,district:delete,ward:view,ward:create,ward:edit,ward:delete,uom:view,uom:create,uom:edit,uom:delete,uom_group:view,uom_group:create,uom_group:edit,uom_group:delete,tax_group:view,tax_group:create,tax_group:edit,tax_group:delete,price_list:view,price_list:create,price_list:edit,price_list:delete,employee:view,employee:create,employee:edit,employee:delete,employee_position:view,employee_position:create,employee_position:edit,employee_position:delete,salesman_type:view,salesman_type:create,salesman_type:edit,salesman_type:delete,company:view,company:edit'
