UPDATE user u JOIN role r ON r.id = u.role_id SET u.permissions = 'sales_order:view,sales_order:create,sales_request:view,sales_request:create,delivery_order:view,delivery_order:create,invoice:view,invoice:create,sales_return:view,sales_return:create,purchase_return:view,goods_receipt:view,goods_issue:view,inventory_transfer:view,stock_take:view,stock_receipt:view,stock:view,product:view,product_category:view,product_group:view,customer_group:view,customer_channel:view,supplier:view,warehouse:view,branch:view,selling_zone:view,route_master:view,region:view,province:view,district:view,ward:view,uom:view,uom_group:view,tax_group:view,price_list:view,employee:view,employee_position:view,salesman_type:view,company:view,customer:view,customer:create,customer:edit,customer:delete'
